import re, os
from pathlib import Path
files = [
 '.skilled/skills/sk-code/sk-code-frontend/references/web-markup-and-css.md',
 '.skilled/skills/sk-code/sk-code-frontend/references/figma-to-code.md',
 '.skilled/skills/sk-code/sk-code-frontend/references/frontend-practice.md',
]
def slug(h):
    h=h.strip().lower()
    h=re.sub(r'[^\w\s-]','',h)
    h=re.sub(r'\s+','-',h)
    return h
def anchors(p):
    out=set(); incode=False
    for line in Path(p).read_text().splitlines():
        if line.startswith('```'): incode=not incode; continue
        if incode: continue
        m=re.match(r'^#{1,6}\s+(.*)$',line)
        if m: out.add(slug(m.group(1)))
    return out
bad=[]
for f in files:
    text=Path(f).read_text()
    for m in re.finditer(r'\[[^\]]*\]\(([^)\s]+)\)',text):
        target=m.group(1)
        if target.startswith(('http://','https://','mailto:','#')):
            if target.startswith('#'):
                if target[1:] not in anchors(f): bad.append((f,target,'missing same-file anchor'))
            continue
        path,_,frag=target.partition('#')
        resolved=(Path(f).parent/path).resolve()
        if not resolved.exists():
            bad.append((f,target,'missing file'))
        elif frag and resolved.suffix=='.md':
            if frag not in anchors(resolved): bad.append((f,target,'missing anchor'))
print('links checked; problems:',len(bad))
for b in bad: print(b)
